style.css:
@-moz-document domain("pikadil.ru") {
header {
    background-color: #363739 !important;
    color: #fff !important;
    border-bottom: 0px !important;
  }

  header .text-accent:not(.text-base) {
    color: #fff !important;
  }

  header .text-accent:hover,
  header .bg-fon button > span,
  header .bg-fon button > svg {
    color: #000716 !important;
  }

  .tracking-tights {
    color: #fff !important;
  }

  header + div:not(.bg-fon) {
    background-color: #28292a !important;
    color: #fff !important;
  }

  header + div .text-accent {
    color: #fff !important;
  }

  .navigation-wrapper .keen-slider__slide a {
    background-color: #46484b !important;
    color: #fff !important;
  }

  footer {
    background-color: #363739 !important;
  }

  footer .text-accent {
    color: #fff !important;
  }

  footer .text-secondary {
    color: #ffffffab !important;
  }

	  .text-accent {
  	  color:#35373b!important;
  }

	:root {
  	color:#35373b!important;
	}
}
